(function () {
  'use strict';

  var NL = String.fromCharCode(10);
  var rawCode = '';
  var matches = [];
  var currentMatch = -1;
  var isMaximized = false;
  var prevSize = null;
  var preMinimizeSize = null;
  var saveTimer = null;
  var rescanTimer = null;
  var scrollRaf = null;
  var toastTimer = null;
  var isDesktop = (window.innerWidth || 0) >= 768;
  var isBallMode = false;
  var isSearchCollapsed = false;

  var MIN_W = 240, MIN_H = 320;
  var MAX_W = 420, MAX_H = 520;
  var BALL_SIZE = 36;
  var IDLE_DELAY = 3000;
  var winW = 320, winH = 500;

  function $(id) { return document.getElementById(id); }
  function escapeHTML(s) {
    return String(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
  }

  var resizeRaf = null, pendingSize = null;
  function flushResize() {
    resizeRaf = null;
    if (!pendingSize) return;
    var p = pendingSize; pendingSize = null;
    try { if (window.nuo && window.nuo.window && window.nuo.window.resize) window.nuo.window.resize(p.w, p.h); } catch (e) {}
  }
  function setWindowSize(w, h, noClamp) {
    if (!noClamp) { w = Math.max(MIN_W, Math.min(MAX_W, Math.round(w))); h = Math.max(MIN_H, Math.min(MAX_H, Math.round(h))); }
    else { w = Math.max(1, Math.round(w)); h = Math.max(1, Math.round(h)); }
    winW = w; winH = h;
    pendingSize = { w: w, h: h };
    if (resizeRaf === null) resizeRaf = requestAnimationFrame(flushResize);
  }

  var idleTimer = null;
  function clearIdle() { clearTimeout(idleTimer); idleTimer = null; if (document.body.classList.contains('idle')) document.body.classList.remove('idle'); }
  function startIdleCountdown() { clearIdle(); idleTimer = setTimeout(function () { if (isBallMode) document.body.classList.add('idle'); }, IDLE_DELAY); }
  function kickIdle() {
    if (document.body.classList.contains('idle')) document.body.classList.remove('idle');
    if (isBallMode) startIdleCountdown();
    else { clearTimeout(idleTimer); idleTimer = null; }
  }
  ['pointerdown','pointermove','pointerup','pointercancel','keydown','keyup','input','focusin','wheel','touchstart','touchmove','touchend','scroll'].forEach(function (ev) {
    document.addEventListener(ev, kickIdle, { passive: true, capture: true });
  });

  function updateMaximizeButton() {
    var btn = $('btn-maximize'); if (!btn) return;
    if (isMaximized) { btn.textContent = '还原'; btn.classList.add('active'); }
    else { btn.textContent = '最大化'; btn.classList.remove('active'); }
  }
  function exitMaximizeFlag() { if (!isMaximized) return; isMaximized = false; document.body.classList.remove('maximized'); updateMaximizeButton(); }
  function toggleMaximize() {
    if (!isMaximized) {
      prevSize = { w: winW, h: winH };
      setWindowSize(MAX_W, MAX_H);
      isMaximized = true;
      document.body.classList.add('maximized');
    } else {
      if (prevSize) setWindowSize(prevSize.w, prevSize.h); else setWindowSize(320, 500);
      isMaximized = false;
      document.body.classList.remove('maximized');
    }
    updateMaximizeButton();
    requestAnimationFrame(function () { syncPadding(); syncScroll(); });
  }

  function minimizeApp() {
    exitMaximizeFlag();
    preMinimizeSize = { w: winW, h: winH };
    isBallMode = true;
    document.body.classList.add('ball');
    setWindowSize(BALL_SIZE, BALL_SIZE, true);
    startIdleCountdown();
  }
  function restoreApp() {
    isBallMode = false;
    document.body.classList.remove('ball');
    clearIdle();
    if (preMinimizeSize) { setWindowSize(preMinimizeSize.w, preMinimizeSize.h, true); preMinimizeSize = null; }
    else setWindowSize(320, 500);
    /* 从球态恢复：强制展开搜索栏 */
    isSearchCollapsed = false;
    updateSearchBarVisibility();
    requestAnimationFrame(function () { syncPadding(); syncScroll(); });
  }
  function closeApp() {
    try { if (window.nuo && window.nuo.window) window.nuo.window.close(); } catch (e) {}
  }

  try {
    if (window.nuo && window.nuo.window && window.nuo.window.dragHandle) {
      var dh = $('drag-header');
      if (dh) window.nuo.window.dragHandle(dh);
      var ball = $('floating-ball');
      if (ball) window.nuo.window.dragHandle(ball);
    }
  } catch (e) {}

  (function () {
    var ball = $('floating-ball');
    if (!ball) return;
    ball.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      restoreApp();
    });
  })();

  (function () {
    var handle = $('resize-handle');
    if (!handle) return;
    var resizing = null;
    handle.addEventListener('pointerdown', function (e) {
      if (e.button !== undefined && e.button !== 0) return;
      e.preventDefault(); e.stopPropagation();
      resizing = { id: e.pointerId, startX: e.clientX, startY: e.clientY, startW: winW, startH: winH };
      try { handle.setPointerCapture(e.pointerId); } catch (err) {}
      document.body.classList.add('resizing');
    });
    handle.addEventListener('pointermove', function (e) {
      if (!resizing || e.pointerId !== resizing.id) return;
      setWindowSize(resizing.startW + (e.clientX - resizing.startX), resizing.startH + (e.clientY - resizing.startY));
    });
    function endResize(e) {
      if (!resizing || e.pointerId !== resizing.id) return;
      resizing = null;
      document.body.classList.remove('resizing');
      if (isMaximized && (winW !== MAX_W || winH !== MAX_H)) exitMaximizeFlag();
      requestAnimationFrame(function () { syncPadding(); syncScroll(); });
    }
    handle.addEventListener('pointerup', endResize);
    handle.addEventListener('pointercancel', endResize);
    handle.addEventListener('lostpointercapture', function (e) { if (resizing && e.pointerId === resizing.id) endResize(e); });
  })();

  var taPaste = $('code-input');
  var taEdit = $('edit-area');
  var highlight = $('highlight-layer');
  var searchInput = $('search-input');
  var searchStatus = $('search-status');
  var searchDropdown = $('search-dropdown');
  var searchBar = $('search-bar');
  var btnCollapse = $('btn-collapse-search');
  var btnExpand = $('btn-expand-search');
  var toastEl = $('app-toast');

  function showToast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove('show'); }, 1500);
  }

  function getActiveTextarea() {
    return $('panel-view').classList.contains('active') ? taEdit : taPaste;
  }

  function doSelectAll() {
    var el = getActiveTextarea();
    var text = el.value || '';
    if (!text) { showToast('没有内容'); return; }
    try { el.focus({ preventScroll: true }); }
    catch (e) { try { el.focus(); } catch (e2) {} }
    try { el.setSelectionRange(0, text.length); } catch (e) { try { el.select(); } catch (e2) {} }
    showToast('已全选 ' + text.length + ' 字符');
  }

  function copyViaFallback(text) {
    try {
      var tmp = document.createElement('textarea');
      tmp.value = text;
      tmp.style.position = 'fixed';
      tmp.style.left = '-9999px';
      tmp.style.top = '0';
      tmp.style.opacity = '0';
      tmp.setAttribute('readonly', '');
      document.body.appendChild(tmp);
      tmp.select();
      tmp.setSelectionRange(0, text.length);
      var ok = false;
      try { ok = document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(tmp);
      return ok;
    } catch (e) { return false; }
  }

  function doCopy() {
    var el = getActiveTextarea();
    var text = el.value || '';
    if (!text) { showToast('没有内容'); return; }
    var fallbackAfterAsync = function () {
      if (copyViaFallback(text)) showToast('已复制 ' + text.length + ' 字符');
      else showToast('复制失败');
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        navigator.clipboard.writeText(text).then(function () {
          showToast('已复制 ' + text.length + ' 字符');
        }).catch(function () {
          fallbackAfterAsync();
        });
      } catch (e) {
        fallbackAfterAsync();
      }
    } else {
      fallbackAfterAsync();
    }
  }

  /* ============ 搜索栏显示控制 ============ */
  function updateSearchBarVisibility() {
    var onViewTab = $('panel-view').classList.contains('active');
    if (!onViewTab) {
      /* 离开搜索查看标签时，重置收起状态，保证下次回来搜索栏会显示 */
      isSearchCollapsed = false;
      searchBar.style.display = 'none';
      btnExpand.classList.remove('visible');
      return;
    }
    if (isSearchCollapsed) {
      searchBar.style.display = 'none';
      btnExpand.classList.add('visible');
    } else {
      searchBar.style.display = 'flex';
      btnExpand.classList.remove('visible');
    }
  }
  function collapseSearch() {
    if (isSearchCollapsed) return;
    isSearchCollapsed = true;
    updateSearchBarVisibility();
    searchDropdown.style.display = 'none';
    try { taEdit.focus({ preventScroll: true }); }
    catch (e) { try { taEdit.focus(); } catch (e2) {} }
  }
  function expandSearch() {
    if (!isSearchCollapsed) { try { searchInput.focus(); } catch (e) {} return; }
    isSearchCollapsed = false;
    updateSearchBarVisibility();
    try { searchInput.focus(); } catch (e) {}
    var v = searchInput.value || '';
    try { searchInput.setSelectionRange(v.length, v.length); } catch (e) {}
  }
  btnCollapse.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); collapseSearch(); });
  btnExpand.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); expandSearch(); });

  try {
    if (window.nuo && window.nuo.storage) {
      window.nuo.storage.get('code').then(function (v) {
        if (typeof v === 'string' && v) {
          taPaste.value = v; taEdit.value = v; rawCode = v; renderHighlight();
        }
      }).catch(function () {});
    }
  } catch (e) {}
  function persistCode(text) {
    try { if (window.nuo && window.nuo.storage) window.nuo.storage.set('code', text).catch(function () {}); } catch (e) {}
  }
  function scheduleSave(text) { clearTimeout(saveTimer); saveTimer = setTimeout(function () { persistCode(text); }, 500); }
  taPaste.addEventListener('input', function () { rawCode = taPaste.value; scheduleSave(rawCode); });

  function syncScroll() {
    if (scrollRaf) return;
    scrollRaf = requestAnimationFrame(function () {
      scrollRaf = null;
      highlight.scrollTop = taEdit.scrollTop;
      highlight.scrollLeft = taEdit.scrollLeft;
    });
  }
  function syncPadding() {
    var sbw = taEdit.offsetWidth - taEdit.clientWidth;
    if (sbw < 0) sbw = 0;
    highlight.style.paddingRight = (12 + sbw) + 'px';
  }
  taEdit.addEventListener('scroll', syncScroll, { passive: true });

  function renderHighlight() {
    var text = taEdit.value;
    if (matches.length === 0) { highlight.textContent = text + NL; return; }
    var html = '';
    var pos = 0;
    for (var i = 0; i < matches.length; i++) {
      var m = matches[i];
      if (m.start > pos) html += escapeHTML(text.substring(pos, m.start));
      var cls = (i === currentMatch) ? ' class="current"' : '';
      html += '<mark' + cls + '>' + escapeHTML(text.substring(m.start, m.end)) + '</mark>';
      pos = m.end;
    }
    if (pos < text.length) html += escapeHTML(text.substring(pos));
    html += NL;
    highlight.innerHTML = html;
  }

  function scanMatches() {
    var q = searchInput.value;
    var text = taEdit.value;
    matches = [];
    currentMatch = -1;
    if (!q) return;
    var lq = q.toLowerCase();
    var lt = text.toLowerCase();
    var idx = 0, guard = 0;
    while (guard++ < 50000) {
      var at = lt.indexOf(lq, idx);
      if (at === -1) break;
      matches.push({ start: at, end: at + q.length });
      idx = at + Math.max(1, q.length);
    }
  }
  function scrollToCurrentMark() {
    var mEl = highlight.querySelector('mark.current');
    if (!mEl) return;
    var top = mEl.offsetTop;
    var h = taEdit.clientHeight;
    var mh = mEl.offsetHeight || 20;
    taEdit.scrollTop = Math.max(0, top - h / 2 + mh / 2);
    syncScroll();
  }
  function gotoMatch(n, focusIt) {
    if (matches.length === 0) { currentMatch = -1; searchStatus.textContent = '0/0'; renderHighlight(); return; }
    currentMatch = ((n % matches.length) + matches.length) % matches.length;
    renderHighlight();
    var m = matches[currentMatch];
    try { taEdit.setSelectionRange(m.start, m.end); } catch (e) {}
    requestAnimationFrame(function () { scrollToCurrentMark(); });
    if (focusIt !== false && isDesktop) {
      try { taEdit.focus({ preventScroll: true }); }
      catch (e) { try { taEdit.focus(); } catch (e2) {} }
    }
    searchStatus.textContent = (currentMatch + 1) + '/' + matches.length;
  }
  function buildDropdown() {
    if (matches.length === 0) { searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none'; return; }
    var text = taEdit.value;
    var max = Math.min(matches.length, 200);
    var html = '';
    for (var i = 0; i < max; i++) {
      var m = matches[i];
      var lineStart = text.lastIndexOf(NL, m.start - 1) + 1;
      var lineEnd = text.indexOf(NL, m.end);
      if (lineEnd === -1) lineEnd = text.length;
      var lineIdx = text.substring(0, m.start).split(NL).length;
      var before = text.substring(Math.max(lineStart, m.start - 20), m.start);
      var midText = text.substring(m.start, m.end);
      var after = text.substring(m.end, Math.min(lineEnd, m.end + 30));
      var preDot = (m.start - 20 > lineStart) ? '…' : '';
      var sufDot = (m.end + 30 < lineEnd) ? '…' : '';
      html += '<div class="drop-item" data-idx="' + i + '">' + '<span class="drop-num">' + lineIdx + '</span>' + escapeHTML(preDot + before) + '<mark>' + escapeHTML(midText) + '</mark>' + escapeHTML(after + sufDot) + '</div>';
    }
    searchDropdown.innerHTML = html;
    searchDropdown.style.display = 'block';
  }

  searchInput.addEventListener('input', function () {
    scanMatches();
    if (matches.length > 0) { gotoMatch(0); buildDropdown(); }
    else { searchStatus.textContent = '0/0'; searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none'; renderHighlight(); }
  });
  searchInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); if (matches.length > 0) gotoMatch(currentMatch + 1); }
    else if (e.key === 'Escape') {
      e.preventDefault();
      if (searchInput.value) {
        searchInput.value = ''; matches = []; currentMatch = -1;
        searchStatus.textContent = '0/0';
        searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
        renderHighlight();
      } else { collapseSearch(); }
    }
  });
  searchInput.addEventListener('focus', function () { if (matches.length > 0) searchDropdown.style.display = 'block'; });
  searchInput.addEventListener('blur', function () { setTimeout(function () { searchDropdown.style.display = 'none'; }, 200); });

  $('btn-prev').addEventListener('click', function () { if (matches.length === 0) return; gotoMatch(currentMatch - 1); });
  $('btn-next').addEventListener('click', function () { if (matches.length === 0) return; gotoMatch(currentMatch + 1); });

  searchDropdown.addEventListener('mousedown', function (e) {
    var node = e.target;
    while (node && node !== this && !(node.classList && node.classList.contains('drop-item'))) node = node.parentNode;
    if (!node || node === this) return;
    e.preventDefault();
    var idx = parseInt(node.getAttribute('data-idx'), 10);
    if (isNaN(idx)) return;
    gotoMatch(idx);
    searchDropdown.style.display = 'none';
  });

  taEdit.addEventListener('input', function () {
    rawCode = taEdit.value;
    scheduleSave(rawCode);
    if (!searchInput.value) { renderHighlight(); return; }
    clearTimeout(rescanTimer);
    rescanTimer = setTimeout(function () {
      var selStart = taEdit.selectionStart;
      scanMatches();
      if (matches.length === 0) {
        searchStatus.textContent = '0/0';
        searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
        renderHighlight(); return;
      }
      var found = -1;
      for (var i = 0; i < matches.length; i++) {
        if (matches[i].start <= selStart && selStart <= matches[i].end) { found = i; break; }
      }
      if (found >= 0) currentMatch = found;
      else if (currentMatch >= matches.length) currentMatch = matches.length - 1;
      else if (currentMatch < 0) currentMatch = 0;
      searchStatus.textContent = (currentMatch + 1) + '/' + matches.length;
      renderHighlight();
      if (searchInput.value) buildDropdown();
    }, 120);
  });

  function switchTab(tab) {
    if (tab === 'view') {
      if (taEdit.value !== taPaste.value) taEdit.value = taPaste.value;
      rawCode = taEdit.value;
      /* 切到搜索查看：重置收起状态，保证搜索栏可见 */
      isSearchCollapsed = false;
      requestAnimationFrame(function () {
        syncPadding();
        scanMatches();
        if (matches.length > 0) { gotoMatch(currentMatch >= 0 ? currentMatch : 0); buildDropdown(); }
        else { renderHighlight(); searchStatus.textContent = '0/0'; }
      });
    } else {
      if (taPaste.value !== taEdit.value) taPaste.value = taEdit.value;
    }
    $('tab-edit').classList.toggle('active', tab === 'edit');
    $('tab-view').classList.toggle('active', tab === 'view');
    $('panel-edit').classList.toggle('active', tab === 'edit');
    $('panel-view').classList.toggle('active', tab === 'view');
    updateSearchBarVisibility();
  }
  $('tab-edit').addEventListener('click', function () { switchTab('edit'); });
  $('tab-view').addEventListener('click', function () { switchTab('view'); });

  function clearAll() {
    taPaste.value = ''; taEdit.value = ''; rawCode = '';
    persistCode('');
    searchInput.value = ''; matches = []; currentMatch = -1;
    searchStatus.textContent = '0/0';
    searchDropdown.innerHTML = ''; searchDropdown.style.display = 'none';
    renderHighlight();
    switchTab('edit');
    showToast('已清空');
  }

  window.addEventListener('resize', function () { requestAnimationFrame(function () { syncPadding(); syncScroll(); }); });

  $('btn-minimize').addEventListener('click', minimizeApp);
  $('btn-clear').addEventListener('click', clearAll);
  $('btn-maximize').addEventListener('click', toggleMaximize);
  $('btn-close').addEventListener('click', closeApp);
  $('btn-select-all').addEventListener('click', doSelectAll);
  $('btn-copy').addEventListener('click', doCopy);

  updateMaximizeButton();
  isBallMode = false;
  clearIdle();
  updateSearchBarVisibility();

  requestAnimationFrame(function () { syncPadding(); renderHighlight(); });

  try { if (window.nuo && window.nuo.ready) window.nuo.ready(); } catch (e) {}
})();

entry.css:
* { box-sizing: border-box; }
html, body {
  background: transparent;
  margin: 0;
  padding: 0;
  font-family: -apple-system, system-ui, sans-serif;
}
#app {
  padding: 16px 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: var(--nuo-fg);
  font-size: 13px;
  background: var(--nuo-bg);
  border-radius: 14px;
  min-width: 280px;
  min-height: 320px;
}

.page { display: flex; flex-direction: column; gap: 14px; display: none; }
.page-title { font-size: 22px; font-weight: 800; text-align: center; color: var(--nuo-fg); letter-spacing: 0.04em; padding: 4px 0 2px; }
.page-title-sm { font-size: 17px; font-weight: 700; color: var(--nuo-fg); flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.page-header { display: flex; align-items: center; gap: 10px; padding-bottom: 6px; border-bottom: 1px solid var(--nuo-border); }
.back-btn { background: none; border: none; color: var(--nuo-accent); font-size: 13px; font-weight: 600; cursor: pointer; padding: 4px 8px; border-radius: 6px; white-space: nowrap; }
.back-btn:hover { background: var(--nuo-surface); }
.back-btn:active { transform: scale(0.95); }

.home-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.home-btn { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 18px 8px 14px; border-radius: 14px; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); cursor: pointer; transition: all 0.15s; text-align: center; min-height: 90px; }
.home-btn:hover { border-color: var(--nuo-accent); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.2); }
.home-btn:active { transform: scale(0.95); }
.home-icon { font-size: 28px; margin-bottom: 4px; }
.home-label { font-size: 14px; font-weight: 700; }
.home-desc { font-size: 10px; color: var(--nuo-fg-dim); margin-top: 2px; }
.home-footer { text-align: center; font-size: 11px; color: var(--nuo-fg-dim); padding-top: 4px; border-top: 1px solid var(--nuo-border); }

.char-list { display: flex; flex-direction: column; gap: 6px; min-height: 120px; max-height: 320px; overflow-y: auto; }
.char-item { display: flex; align-items: center; justify-content: space-between; padding: 10px 12px; border-radius: 10px; background: var(--nuo-surface); border: 1px solid var(--nuo-border); cursor: pointer; transition: all 0.12s; }
.char-item:hover { border-color: var(--nuo-accent); }
.char-item:active { transform: scale(0.98); }
.char-item .char-info { flex: 1; min-width: 0; }
.char-item .char-name { font-weight: 700; font-size: 14px; }
.char-item .char-meta { font-size: 11px; color: var(--nuo-fg-dim); }
.char-item .char-status { font-size: 10px; padding: 2px 10px; border-radius: 12px; background: var(--nuo-border); color: var(--nuo-fg-dim); flex-shrink: 0; }
.char-item .char-status.complete { background: #2a4a3a; color: #8dd0a0; }
.empty-state { text-align: center; color: var(--nuo-fg-dim); font-size: 13px; padding: 28px 0; }

.view-actions { display: flex; gap: 4px; flex-shrink: 0; }
.view-btn { padding: 4px 8px; border-radius: 6px; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); font-size: 15px; cursor: pointer; transition: all 0.12s; line-height: 1.4; }
.view-btn:hover { border-color: var(--nuo-accent); }
.view-btn:active { transform: scale(0.9); }
.view-btn-danger:hover { border-color: #d07070; color: #d07070; }
.view-content { display: flex; flex-direction: column; gap: 6px; max-height: 340px; overflow-y: auto; }
.view-row { display: flex; padding: 3px 0; border-bottom: 1px solid var(--nuo-border); font-size: 13px; }
.view-row .view-label { width: 70px; flex-shrink: 0; color: var(--nuo-fg-dim); font-weight: 600; }
.view-row .view-value { flex: 1; }
.view-attr-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 2px 8px; padding: 4px 0; }
.view-attr-item { display: flex; justify-content: space-between; font-size: 13px; padding: 2px 0; }
.view-attr-item .attr-label { color: var(--nuo-fg-dim); }
.view-attr-item .attr-value { font-weight: 700; }
.view-status-badge { display: inline-block; font-size: 10px; padding: 2px 12px; border-radius: 12px; background: var(--nuo-border); color: var(--nuo-fg-dim); }
.view-status-badge.complete { background: #2a4a3a; color: #8dd0a0; }
.view-section-title { font-weight: 700; font-size: 12px; color: var(--nuo-fg-dim); margin-top: 4px; padding-top: 4px; border-top: 1px solid var(--nuo-border); }
.view-text-block { font-size: 13px; padding: 6px 8px; background: var(--nuo-surface); border-radius: 6px; white-space: pre-wrap; word-break: break-word; border: 1px solid var(--nuo-border); }
.view-derived-grid { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr 1fr; gap: 4px; padding: 4px 0; }
.view-derived-item { display: flex; flex-direction: column; align-items: center; padding: 4px 2px; border-radius: 4px; background: var(--nuo-surface); border: 1px solid var(--nuo-border); }
.view-derived-item .label { font-size: 10px; color: var(--nuo-fg-dim); }
.view-derived-item .value { font-weight: 700; font-size: 14px; }

.tab-bar { display: flex; gap: 0; border-bottom: 2px solid var(--nuo-border); margin-bottom: 2px; }
.tab-btn { padding: 8px 16px; border: none; background: transparent; color: var(--nuo-fg-dim); font-size: 13px; font-weight: 600; cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -2px; transition: all 0.15s; }
.tab-btn:hover { color: var(--nuo-fg); }
.tab-btn.active { color: var(--nuo-accent); border-bottom-color: var(--nuo-accent); }
.tab-btn:active { transform: scale(0.95); }

.current-content { display: flex; flex-direction: column; gap: 10px; max-height: 320px; overflow-y: auto; padding: 2px 0; }
.current-tab { display: none; flex-direction: column; gap: 8px; }
.current-tab.active { display: flex; }
.current-attr-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px 12px; }
.current-attr-item { display: flex; justify-content: space-between; padding: 4px 6px 4px 10px; border-radius: 6px; background: var(--nuo-surface); border: 1px solid var(--nuo-border); }
.current-attr-item .label { font-size: 12px; color: var(--nuo-fg-dim); }
.current-attr-item .value { font-weight: 700; font-size: 14px; }
.current-status-list { display: flex; flex-direction: column; gap: 6px; width: 100%; }
.current-status-item { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 6px; background: var(--nuo-surface); border: 1px solid var(--nuo-border); }
.current-status-item .label { font-size: 13px; font-weight: 700; color: var(--nuo-fg); min-width: 42px; }
.current-status-item .value-input { width: 44px; padding: 2px 4px; border: none; background: transparent; color: var(--nuo-fg); font-size: 14px; font-weight: 700; text-align: center; outline: none; border-bottom: 1px solid transparent; }
.current-status-item .value-input:focus { border-bottom-color: var(--nuo-accent); }
.current-status-item .status-input { flex: 1; padding: 2px 6px; border: none; background: transparent; color: var(--nuo-fg); font-size: 13px; outline: none; border-bottom: 1px solid transparent; min-width: 40px; }
.current-status-item .status-input:focus { border-bottom-color: var(--nuo-accent); }
.current-status-item .sep { color: var(--nuo-fg-dim); font-size: 12px; }
.current-textarea { width: 100%; padding: 8px 10px; border-radius: 8px; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); font-size: 13px; font-family: inherit; resize: vertical; min-height: 60px; }
.current-textarea:focus { outline: none; border-color: var(--nuo-accent); }

/* 当前属性 - 技能列表 */
.current-skill-item {
  display: flex;
  justify-content: space-between;
  padding: 3px 8px;
  border-bottom: 1px solid var(--nuo-border);
  font-size: 12px;
}
.current-skill-item .cs-name { font-weight: 600; }
.current-skill-item .cs-value { font-weight: 700; color: var(--nuo-accent); }
.current-skill-item .cs-detail { font-size: 10px; color: var(--nuo-fg-dim); }

/* ===== 疯狂发作样式 ===== */
.madness-section {
  margin-top: 6px;
  padding: 8px 10px;
  background: var(--nuo-surface);
  border-radius: 8px;
  border: 1px solid var(--nuo-border);
}
.madness-title {
  font-size: 13px;
  font-weight: 700;
  color: #d07070;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.madness-title .madness-icon { font-size: 16px; }
.madness-row {
  display: flex;
  gap: 6px;
  align-items: center;
  flex-wrap: wrap;
}
.madness-btn {
  padding: 3px 12px;
  border-radius: 6px;
  border: 1px solid var(--nuo-border);
  background: var(--nuo-bg);
  color: var(--nuo-fg);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.15s;
}
.madness-btn:hover { border-color: #d07070; background: rgba(208,112,112,0.08); }
.madness-btn:active { transform: scale(0.95); }
.madness-sub-btn {
  padding: 2px 10px;
  border-radius: 4px;
  border: 1px solid rgba(217,180,95,0.3);
  background: rgba(217,180,95,0.08);
  color: var(--nuo-accent);
  font-size: 10px;
  cursor: pointer;
  transition: all 0.15s;
}
.madness-sub-btn:hover { border-color: var(--nuo-accent); background: rgba(217,180,95,0.15); }
.madness-sub-btn:active { transform: scale(0.95); }
.madness-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 4px;
}
.madness-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--nuo-bg);
  border: 1px solid var(--nuo-border);
  font-size: 11px;
  line-height: 1.4;
}
.madness-item .mi-type {
  font-weight: 700;
  color: #d07070;
  flex-shrink: 0;
  font-size: 10px;
}
.madness-item .mi-content { flex: 1; }
.madness-item .mi-content .mi-name { font-weight: 700; color: var(--nuo-fg); }
.madness-item .mi-content .mi-desc { color: var(--nuo-fg-dim); }
.madness-item .mi-remove {
  cursor: pointer;
  color: var(--nuo-fg-dim);
  font-size: 14px;
  flex-shrink: 0;
  transition: color 0.15s;
}
.madness-item .mi-remove:hover { color: #d07070; }
.madness-empty {
  font-size: 11px;
  color: var(--nuo-fg-dim);
  opacity: 0.6;
  padding: 4px 0;
}

/* ===== 新增：子骰子区域 ===== */
.madness-sub-area {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-left: 8px;
  padding-left: 8px;
  border-left: 2px solid var(--nuo-border);
}
.madness-sub-area .sub-label {
  font-size: 10px;
  color: var(--nuo-fg-dim);
  font-weight: 600;
}

.form-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 4px 0 8px; border-bottom: 1px solid var(--nuo-border); }
.form-nav-btn { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); font-size: 18px; font-weight: 300; cursor: pointer; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.form-nav-btn:hover { border-color: var(--nuo-accent); }
.form-nav-btn:disabled { opacity: 0.3; cursor: default; }
.form-nav-btn:disabled:hover { border-color: var(--nuo-border); }
.form-steps { display: flex; align-items: center; gap: 0; flex: 1; justify-content: center; }
.step-dot { width: 28px; height: 28px; border-radius: 50%; border: 2px solid var(--nuo-border); background: var(--nuo-bg); color: var(--nuo-fg-dim); font-size: 12px; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; transition: all 0.2s; }
.step-dot.active { border-color: var(--nuo-accent); background: var(--nuo-accent); color: var(--nuo-bg); }
.step-dot.done { border-color: var(--nuo-accent); background: var(--nuo-surface); color: var(--nuo-accent); }
.step-line { flex: 1; height: 2px; background: var(--nuo-border); min-width: 16px; transition: all 0.2s; }
.step-line.done { background: var(--nuo-accent); }
.form-step-label { text-align: center; font-size: 13px; font-weight: 700; color: var(--nuo-fg); padding: 2px 0; }
.form-step { display: none; flex-direction: column; gap: 10px; }
.form-step.active { display: flex; }

.form-group { display: flex; flex-direction: column; gap: 3px; }
.form-label { font-size: 12px; font-weight: 600; color: var(--nuo-fg-dim); }
.form-label .required { color: #d07070; }
.form-input { padding: 8px 10px; border-radius: 8px; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); font-size: 14px; width: 100%; transition: border-color 0.15s; font-family: inherit; }
.form-input:focus { outline: none; border-color: var(--nuo-accent); }
.form-input::placeholder { color: var(--nuo-fg-dim); opacity: 0.5; }
select.form-input { appearance: auto; }
textarea.form-input { resize: vertical; font-family: inherit; }
.form-row { display: flex; gap: 10px; }
.form-row .form-group { flex: 1; }

.attr-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px 10px; }
.attr-item { display: flex; align-items: center; justify-content: space-between; padding: 4px 6px 4px 10px; border-radius: 6px; background: var(--nuo-surface); border: 1px solid var(--nuo-border); }
.attr-label { font-size: 12px; font-weight: 600; }
.attr-abbr { font-size: 10px; color: var(--nuo-fg-dim); font-weight: 400; margin-left: 2px; }
.attr-input { width: 42px; padding: 4px 2px; text-align: center; border: none; background: transparent; color: var(--nuo-fg); font-size: 15px; font-weight: 700; }
.attr-input:focus { outline: 1px solid var(--nuo-accent); border-radius: 4px; }
.attr-input::-webkit-inner-spin-button { -webkit-appearance: none; }
.attr-input[type=number] { -moz-appearance: textfield; }
.attr-input:disabled { opacity: 0.5; cursor: not-allowed; }

.creation-toggle { display: flex; gap: 4px; background: var(--nuo-surface); border-radius: 10px; padding: 4px; border: 1px solid var(--nuo-border); }
.creation-btn { flex: 1; padding: 6px 0; border: none; border-radius: 8px; background: transparent; color: var(--nuo-fg-dim); font-size: 14px; font-weight: 700; cursor: pointer; transition: all 0.2s; }
.creation-btn.active { background: var(--nuo-accent); color: var(--nuo-bg); }
.creation-btn:hover:not(.active) { background: var(--nuo-border); }
.creation-btn:active { transform: scale(0.96); }

.buy-info { display: flex; justify-content: space-between; align-items: center; padding: 4px 8px; background: var(--nuo-surface); border-radius: 6px; font-size: 13px; border: 1px solid var(--nuo-border); }
.buy-info strong { color: var(--nuo-accent); font-size: 16px; }
.buy-warning { color: #d07070; font-weight: 700; font-size: 13px; }

.random-info { display: flex; flex-direction: column; gap: 8px; }
.random-roll-btn { padding: 10px 0; border: none; border-radius: 10px; background: linear-gradient(135deg, #5a3a4a, #3a2a3a); color: #f0e6d2; font-size: 18px; font-weight: 700; cursor: pointer; transition: all 0.15s; letter-spacing: 0.05em; }
.random-roll-btn:hover { opacity: 0.85; transform: scale(1.01); }
.random-roll-btn:active { transform: scale(0.96); }
.random-roll-btn:disabled { opacity: 0.4; cursor: default; transform: none; }
.random-sets { display: flex; flex-direction: column; gap: 6px; max-height: 180px; overflow-y: auto; }
.random-set { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr 1fr 1fr 1fr 1fr; gap: 4px; padding: 6px 8px; border-radius: 8px; background: var(--nuo-surface); border: 2px solid var(--nuo-border); cursor: pointer; transition: all 0.15s; font-size: 12px; }
.random-set:hover { border-color: var(--nuo-accent); }
.random-set:active { transform: scale(0.97); }
.random-set .set-label { font-weight: 600; color: var(--nuo-fg-dim); font-size: 10px; grid-column: span 8; text-align: center; padding-bottom: 2px; border-bottom: 1px solid var(--nuo-border); }
.random-set .set-item { text-align: center; padding: 2px 0; }
.random-set .set-item .abbr { display: block; font-size: 8px; color: var(--nuo-fg-dim); }
.random-set .set-item .val { font-weight: 700; font-size: 14px; }
.random-set.selected { border-color: var(--nuo-accent); background: rgba(217,180,95,0.12); }
.random-tip { padding: 8px 10px; border-radius: 8px; background: rgba(217,180,95,0.08); border: 1px solid rgba(217,180,95,0.2); font-size: 12px; line-height: 1.6; color: var(--nuo-fg-dim); }
.random-tip .tip-title { font-weight: 700; color: var(--nuo-fg); margin-bottom: 4px; }

.luck-item { background: rgba(217,180,95,0.06) !important; border-color: rgba(217,180,95,0.3) !important; }
.luck-input-group { display: flex; align-items: center; gap: 4px; }
.luck-input-group .attr-input { width: 42px; }
.luck-roll-btn { width: 28px; height: 28px; border-radius: 50%; border: 1px solid var(--nuo-border); background: var(--nuo-surface); color: var(--nuo-fg); font-size: 13px; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.15s; }
.luck-roll-btn:hover { border-color: var(--nuo-accent); background: var(--nuo-accent); color: var(--nuo-bg); }
.luck-roll-btn:active { transform: scale(0.9); }
