  background: transparent;
}
.char-list::-webkit-scrollbar-thumb, .view-content::-webkit-scrollbar-thumb, .current-content::-webkit-scrollbar-thumb,
.occupation-list::-webkit-scrollbar-thumb, .occupation-detail::-webkit-scrollbar-thumb, .occ-detail-skills::-webkit-scrollbar-thumb,
.random-sets::-webkit-scrollbar-thumb, .skill-list-container::-webkit-scrollbar-thumb,
.weapon-info::-webkit-scrollbar-thumb {
  background: var(--nuo-border);
  border-radius: 4px;
}

@media (max-width: 400px) {
  .home-grid { grid-template-columns: 1fr 1fr; }
  .current-attr-grid { grid-template-columns: 1fr 1fr; }
  .attr-grid { grid-template-columns: 1fr 1fr; }
  .view-attr-grid { grid-template-columns: 1fr 1fr; }
  .occupation-panel { flex-direction: column; max-height: 300px; }
  .occupation-list { flex: none; border-right: none; border-bottom: 1px solid var(--nuo-border); max-height: 120px; }
  .occupation-detail { max-height: 160px; }
  .occupation-search { flex-wrap: wrap; }
  .occupation-id-input { flex: 0 0 80px; }
  .random-set { grid-template-columns: 1fr 1fr 1fr 1fr; font-size: 10px; }
  .random-set .set-label { grid-column: span 4; }
  .random-set .set-item .val { font-size: 12px; }
  .derived-grid { grid-template-columns: 1fr 1fr 1fr; }
  .view-derived-grid { grid-template-columns: 1fr 1fr 1fr; }
  .skill-top-panel { flex-direction: column; gap: 4px; }
  .skill-points-summary { flex: none; flex-direction: row; flex-wrap: wrap; justify-content: space-around; }
  .skill-points-summary .sp-item { flex: 1; min-width: 50px; }
  .skill-row { grid-template-columns: 1fr 32px 38px 38px 38px; font-size: 10px; }
  .skill-header { grid-template-columns: 1fr 32px 38px 38px 38px; font-size: 8px; }
  .skill-row .s-input { width: 32px; font-size: 10px; }
  .skill-row .s-name { font-size: 10px; }
  .personal-talent-list .pt-input { max-width: 80px; min-width: 50px; font-size: 10px; }
  .optional-weapons .weapon-selector select { font-size: 10px; }
  .weapon-info { font-size: 9px; }
  .skill-replacement-list .sr-item select,
  .skill-replacement-list .sr-item input { min-width: 40px; max-width: 100px; font-size: 10px; }
  .bg-grid { grid-template-columns: 1fr; }
  .madness-item { font-size: 10px; flex-wrap: wrap; }
}
/* ===== 我的模组 ===== */
.module-page { display: flex; flex-direction: column; gap: 14px; display: none; }
.module-page.active { display: flex; }

.module-home-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.module-home-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 18px 8px 14px;
  border-radius: 14px;
  border: 1px solid var(--nuo-border);
  background: var(--nuo-surface);
  color: var(--nuo-fg);
  cursor: pointer;
  transition: all 0.15s;
  text-align: center;
  min-height: 80px;
}
.module-home-btn:hover {
  border-color: var(--nuo-accent);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,0,0,0.2);
}
.module-home-btn:active { transform: scale(0.95); }
.module-home-btn .module-icon { font-size: 28px; margin-bottom: 4px; }
.module-home-btn .module-label { font-size: 14px; font-weight: 700; }
.module-home-btn .module-desc { font-size: 10px; color: var(--nuo-fg-dim); margin-top: 2px; }

.module-current-display {
  display: flex !important;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 8px;
}

.module-recent {
  border-top: 1px solid var(--nuo-border);
  padding-top: 10px;
  margin-top: 4px;
}
.module-recent-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--nuo-fg-dim);
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.module-recent-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.module-recent-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 10px;
  border-radius: 6px;
  background: var(--nuo-surface);
  border: 1px solid var(--nuo-border);
  cursor: pointer;
  transition: all 0.12s;
}
.module-recent-item:hover { border-color: var(--nuo-accent); }
.module-recent-item .mri-name { font-weight: 600; font-size: 13px; }
.module-recent-item .mri-meta { font-size: 10px; color: var(--nuo-fg-dim); }
.module-recent-item .mri-badge {
  font-size: 9px;
  padding: 1px 8px;
  border-radius: 10px;
  background: var(--nuo-accent);
  color: var(--nuo-bg);
}
.module-recent-empty {
  font-size: 12px;
  color: var(--nuo-fg-dim);
  opacity: 0.6;
  padding: 8px 0;
}

/* 模组列表 */
.module-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 320px;
  overflow-y: auto;
}
.module-card {
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--nuo-surface);
  border: 1px solid var(--nuo-border);
  cursor: pointer;
  transition: all 0.12s;
}
.module-card:hover { border-color: var(--nuo-accent); }
.module-card:active { transform: scale(0.98); }
.module-card .mc-name { font-weight: 700; font-size: 15px; }
.module-card .mc-brief { font-size: 12px; color: var(--nuo-fg-dim); margin-top: 2px; }
.module-card .mc-meta {
  font-size: 10px;
  color: var(--nuo-fg-dim);
  margin-top: 4px;
  display: flex;
  justify-content: space-between;
  opacity: 0.6;
}
.mc-badge-current {
  font-size: 9px;
  padding: 1px 10px;
  border-radius: 10px;
  background: #2a4a3a;
  color: #8dd0a0;
  margin-left: 6px;
}
.module-empty {
  text-align: center;
  color: var(--nuo-fg-dim);
  font-size: 13px;
  padding: 28px 0;
}

/* 模组表单 */
.module-form { display: flex; flex-direction: column; gap: 10px; }
.module-form .form-actions { margin-top: 4px; }

/* 查看模组 */
.m-view-brief {
  font-size: 13px;
  color: var(--nuo-fg-dim);
  padding: 4px 0;
  border-bottom: 1px solid var(--nuo-border);
}
.m-view-controls {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.m-paginate-btn {
  padding: 4px 14px;
  border-radius: 6px;
  border: 1px solid var(--nuo-border);
  background: var(--nuo-surface);
  color: var(--nuo-fg);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s;
}
.m-paginate-btn:hover { border-color: var(--nuo-accent); }
.m-paginate-btn:active { transform: scale(0.95); }
.m-view-info { font-size: 11px; color: var(--nuo-fg-dim); }

.m-view-content {
  flex: 1;
  min-height: 120px;
  max-height: 280px;
  overflow-y: auto;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--nuo-surface);
  border: 1px solid var(--nuo-border);
  font-size: 13px;
  line-height: 1.8;
  white-space: pre-wrap;
  word-break: break-word;
}
.m-view-content .m-page {
  display: none;
}
.m-view-content .m-page.active {
  display: block;
}
.m-view-content .m-page-number {
  font-size: 10px;
  color: var(--nuo-fg-dim);
  text-align: center;
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px solid var(--nuo-border);
}

.m-view-nav {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: center;
  padding-top: 6px;
  border-top: 1px solid var(--nuo-border);
}
.m-nav-btn {
  padding: 4px 14px;
  border-radius: 6px;
  border: 1px solid var(--nuo-border);
  background: var(--nuo-surface);
  color: var(--nuo-fg);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s;
}
.m-nav-btn:hover { border-color: var(--nuo-accent); }
.m-nav-btn:disabled { opacity: 0.3; cursor: default; }
.m-nav-btn:disabled:hover { border-color: var(--nuo-border); }
.m-nav-btn:active:not(:disabled) { transform: scale(0.95); }
#mViewPageInfo { font-size: 12px; font-weight: 600; color: var(--nuo-fg-dim); }

/* ===== 书签 ===== */
.m-view-bookmarks .bookmark-tag {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 8px 1px 6px;
  border-radius: 10px;
  background: rgba(217,180,95,0.15);
  border: 1px solid rgba(217,180,95,0.3);
  font-size: 10px;
  color: var(--nuo-fg);
  cursor: pointer;
  transition: all 0.12s;
}
.m-view-bookmarks .bookmark-tag:hover {
  border-color: var(--nuo-accent);
  background: rgba(217,180,95,0.25);
}
.m-view-bookmarks .bookmark-tag .bm-remove {
  font-size: 11px;
  color: var(--nuo-fg-dim);
  cursor: pointer;
  margin-left: 2px;
}
.m-view-bookmarks .bookmark-tag .bm-remove:hover {
  color: #d07070;
}
.m-view-bookmarks .bookmark-tag.current {
  border-color: var(--nuo-accent);
  background: rgba(217,180,95,0.3);
}

/* ===== 笔记 ===== */
.m-view-notes .note-item {
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--nuo-bg);
  border: 1px solid var(--nuo-border);
  font-size: 11px;
  line-height: 1.4;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 6px;
}
.m-view-notes .note-item .note-content {
  flex: 1;
  word-break: break-word;
}
.m-view-notes .note-item .note-meta {
  font-size: 9px;
  color: var(--nuo-fg-dim);
  flex-shrink: 0;
  margin-top: 2px;
}
.m-view-notes .note-item .note-del {
  cursor: pointer;
  color: var(--nuo-fg-dim);
  font-size: 13px;
  flex-shrink: 0;
  transition: color 0.15s;
}
.m-view-notes .note-item .note-del:hover {
  color: #d07070;
}
.m-view-notes .note-empty {
  font-size: 11px;
  color: var(--nuo-fg-dim);
  opacity: 0.6;
  padding: 2px 0;
}

@media (max-width: 400px) {
  .module-home-grid { grid-template-columns: 1fr 1fr; }
  .module-home-btn { min-height: 70px; padding: 12px 6px; }
  .module-home-btn .module-icon { font-size: 22px; }
  .module-home-btn .module-label { font-size: 12px; }
  .module-home-btn .module-desc { font-size: 9px; }
  .m-view-content { max-height: 200px; font-size: 12px; }
}
